llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "KNI-272, a closely related peptidomimetic protease inhibitor sharing the hydroxyethylamine and tert-butylamide framework, had absolute oral bioavailability of 36.4% when given post-prandially as a capsule in patients, directly supporting F >= 20% under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Atazanavir, a peptidomimetic HIV protease inhibitor, has oral bioavailability >90% when administered with food, demonstrating that this structural class can achieve high oral bioavailability in the fed state.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Paritaprevir, a peptidomimetic protease inhibitor, showed absolute oral bioavailability of 52.6% in healthy volunteers, supporting high F for peptidomimetic compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Esaxerenone had absolute bioavailability of 90.8% postprandially in healthy subjects, providing additional fed-state evidence that high F is achievable despite lipophilic character.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Sulpiride absolute bioavailability was 27-34% in humans, above the 20% threshold, supporting that even incompletely absorbed drugs can meet the F >= 20% criterion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Danavorexton had poor oral bioavailability requiring IV infusion, but it is a non-peptidic small molecule with different physicochemical liabilities, limiting transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "Argatroban has poor oral bioavailability in humans, but its strongly ionizable guanidine and carboxylate groups are absent in the query, so this low-F evidence is weakly transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C17"],
      "claim": "Propafenone F dropped to 4% only under rifampin induction, a co-treatment condition not matching the fed-state query, and therefore does not inform baseline oral bioavailability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Prediction is high (F >= 20%). The closest structural analog KNI-272 achieved 36.4% absolute oral bioavailability post-prandially, and other peptidomimetic protease inhibitors such as atazanavir (>90% with food) and paritaprevir (52.6%) support high F under fed conditions. Low-F comparators are structurally dissimilar or confounded by enzyme induction/ionization, so they do not override the strong supportive transfer.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule itself.",
    "The exact impact of the benzylthio and decahydroisoquinoline modifications relative to KNI-272 on absorption is unknown.",
    "No solubility or dissolution data for the query in the fed state.",
    "Poor-F comparators (danavorexton, argatroban) are not close structural analogs to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

